mapper.select:
SELECT st.*,
       stg.sys_template_group_name sysTemplateGroupName,
       sdi.sys_dict_item_name      sysTemplateManufacturerName,
       sdi2.sys_dict_item_name     sysTemplateCategoryName
FROM sys_template st
         INNER JOIN sys_template_group stg ON st.sys_template_group_id = stg.sys_template_group_id
         LEFT JOIN sys_dict_item sdi  ON sdi.sys_dict_item_id = st.sys_template_manufacturer_id and sdi.sys_dict_id = 1
         LEFT JOIN sys_dict_item sdi2  ON sdi2.sys_dict_item_id = st.sys_template_category and sdi2.sys_dict_id = 2
WHERE st.sys_template_group_id = #{query.sysTemplateGroupId}


    AND st.sys_template_name LIKE CONCAT('%', #{query.sysTemplateName}, '%')



    AND st.sys_template_code LIKE CONCAT('%', #{query.sysTemplateCode}, '%')



    AND st.sys_template_status = #{query.sysTemplateStatus}



    AND st.sys_template_type = #{query.sysTemplateType}



    AND st.sys_template_approve = #{query.sysTemplateApprove}



    AND st.sys_template_approve_reject LIKE CONCAT('%', #{query.sysTemplateApproveReject}, '%')



    AND st.sys_template_approve_create_by = #{query.sysTemplateApproveCreateBy}



    AND st.sys_template_delete = 0



    AND st.sys_template_delete = #{query.sysTemplateDelete}


ORDER BY st.sys_template_sort
